mapper.select:
SELECT A.CONT_ID AS contId , A.SALES_ID AS salesId , A.CONT_NM AS contNm , A.CONT_AMT AS contAmt , A.START_DT AS startDt , A.END_DT AS endDt , A.CONT_DT AS contDt , A.PIC_USER_ID AS picUserId , B.USER_NM AS picUserName , A.CONT_STATUS AS contStatus FROM TB_CONTRACT A LEFT JOIN TB_USER B ON A.PIC_USER_ID = B.USER_ID WHERE A.DEL_YN = 'N'
AND A.CONT_NM LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY A.CONT_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
INSERT INTO TB_CONTRACT (
    SALES_ID, CONT_NM, CONT_AMT, START_DT, END_DT, CONT_DT, PIC_USER_ID, CONT_STATUS, CONT_REMARK
) VALUES (
    #{salesId}, #{contNm}, #{contAmt}, #{startDt}, #{endDt}, #{contDt}, #{picUserId}, #{contStatus}, #{contRemark}
)

mapper.update:
        UPDATE TB_CONTRACT SET
              SALES_ID = #{salesId}
            , CONT_NM = #{contNm}
            , CONT_AMT = #{contAmt}
            , START_DT = NULLIF(#{startDt}, '')
            , END_DT = NULLIF(#{endDt}, '')
            , CONT_DT = NULLIF(#{contDt}, '')
            , PIC_USER_ID = #{picUserId}
            , CONT_STATUS = #{contStatus}
            , CONT_REMARK = #{contRemark}
            , LAST_UPDUSR_ID = #{lastUpdusrId}
	        , LAST_UPDT_PNTTM = NOW()
        WHERE CONT_ID = #{contId}

UPDATE TB_CONTRACT SET 
      DEL_YN = 'Y'
    , LAST_UPDUSR_ID = #{lastUpdusrId}
    , LAST_UPDT_PNTTM = NOW()
WHERE CONT_ID = #{contId}
